(7304245, 1139616, 96751, '<td valign="top">Not my traditional idea of negative space but this is really terrific. No doubt about where the eye should go. Love this environmental portrait</td>', 'Not my traditional idea of negative space but this is really terrific. No doubt about where the eye should go. Love this environmental portrait', '2015-01-19 20:33:46.000000', NULL, 1),
