(7305865, 1139405, 13077, '<td valign="top">Now that looks like a good time!</td>', 'Now that looks like a good time!', '2015-01-22 21:18:53.000000', NULL, 1),
(7305866, 1139647, 13077, '<td valign="top">Nicely done - good definition in the mostly light tones and the grain helps it look substantial.</td>', 'Nicely done - good definition in the mostly light tones and the grain helps it look substantial.', '2015-01-22 21:19:30.000000', NULL, 1),
(7305867, 1139305, 13077, '<td valign="top">I like it. The pose the bird is in looks great, and the processing style and element to tie it in with the ground works well.</td>', 'I like it. The pose the bird is in looks great, and the processing style and element to tie it in with the ground works well.', '2015-01-22 21:20:16.000000', NULL, 1),
(7305868, 1139174, 13077, '<td valign="top">I really like this. It reminds me of places I really enjoy, and the textures you''ve highlighted in the rocks are fascinating. The two guys also really work well to give it scale and are positioned nicely.</td>', 'I really like this. It reminds me of places I really enjoy, and the textures you''ve highlighted in the rocks are fascinating. The two guys also really work well to give it scale and are positioned nicely.', '2015-01-22 21:23:16.000000', NULL, 1),
(7305869, 1139217, 13077, '<td valign="top">I really like the shapes and textures here, but it does look like the focus was set on the wall and not the man''s face. Still so visually strong it''s a 6 from me, would probably have been 7 or 8 if the man''s face was fully in focus.</td>', 'I really like the shapes and textures here, but it does look like the focus was set on the wall and not the man''s face. Still so visually strong it''s a 6 from me, would probably have been 7 or 8 if the man''s face was fully in focus.', '2015-01-22 21:25:24.000000', NULL, 1),
