(7305911, 1139405, 138630, '<td valign="top">So cute and what a great time he is having.  Terrible two''s coming up :)</td>', 'So cute and what a great time he is having.  Terrible two''s coming up :)', '2015-01-22 23:08:42.000000', NULL, 1),
(7305912, 1139463, 138630, '<td valign="top">Love the light, the tones, the dripping water - and his look of intent study of whatever creature he has found.</td>', 'Love the light, the tones, the dripping water - and his look of intent study of whatever creature he has found.', '2015-01-22 23:09:23.000000', NULL, 1),
